import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Profiles, friends and alliances","description":"","frontmatter":{"pageId":"players/community","contentRevision":1},"headers":[],"relativePath":"en/players/community.md","filePath":"en/players/community.md"}'),r={name:"en/players/community.md"};function s(l,e,o,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="profiles-friends-and-alliances" tabindex="-1">Profiles, friends and alliances <a class="header-anchor" href="#profiles-friends-and-alliances" aria-label="Permalink to &quot;Profiles, friends and alliances&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>In <strong>Players → Social</strong>, edit your biography, invitation preferences and notifications. Find a player, request friendship, or create/join an alliance. Its owner invites members, transfers ownership or disbands it. Alliance chat is visible to current members from their join time and is not relayed to Discord.</p><p>The treasury accepts wallet contributions. The owner sets daily withdrawal allowances; spending is counted per UTC day and does not reset on leaving/rejoining. Leaving does not refund contributions; disbanding pays the entire balance to the current owner. Transfer ownership deliberately.</p><p>Allies are protected against mutual harmful attacks and incidents. Joining with conflicting queued hostility may be refused.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Biography: 500 characters; directory: up to 200 players; 100 friends, 16 alliance members, one alliance per player. Invitations expire in 7 days with up to 32 incoming/outgoing. Transactions cap at 1 billion, treasury at 1 trillion. Members&#39; freeze/debt/threat state may block withdrawal.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./chat-pings">Chat, messages and pings</a></li><li><a href="./guild-influence">Guild influence</a></li><li><a href="./economy">Wallet, mail and market</a></li></ul>',10)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
